select distinct po1_0.ID,po1_0.CUSTOMER_ID,c1_0.ID,c1_0.CITY,c1_0.COUNTRY,c1_0.STREET,c1_0.ZIP,c1_0.CREATED_AT,c1_0.EMAIL,c1_0.FIRST_NAME,c1_0.LAST_NAME,l1_0.ORDER_ID,l1_0.ID,l1_0.LINE_NO,l1_0.PRODUCT_ID,l1_0.QUANTITY,l1_0.UNIT_PRICE,po1_0.ORDER_DATE,po1_0.STATUS,po1_0.TOTAL,po1_0.VERSION from ORDERS po1_0 join CUSTOMER c1_0 on c1_0.ID=po1_0.CUSTOMER_ID join ORDER_LINE l1_0 on po1_0.ID=l1_0.ORDER_ID where po1_0.ID between ? and ? order by po1_0.ID;

